/* Zefirok local FloatingUIDOM-compatible positioning runtime.
 * Implements the subset used by the game tooltips: autoUpdate,
 * computePosition, offset, flip, shift and size. No network access required.
 */
(function(global){
  'use strict';
  if (!global) return;

  const toNumber = (value, fallback = 0) => Number.isFinite(Number(value)) ? Number(value) : fallback;
  const paddingValue = (value) => {
    if (typeof value === 'number') return { top:value, right:value, bottom:value, left:value };
    const p = value && typeof value === 'object' ? value : {};
    return {
      top: toNumber(p.top, 0),
      right: toNumber(p.right, 0),
      bottom: toNumber(p.bottom, 0),
      left: toNumber(p.left, 0)
    };
  };
  const viewport = () => {
    const doc = global.document?.documentElement;
    return {
      width: Math.max(0, toNumber(global.innerWidth, doc?.clientWidth || 0)),
      height: Math.max(0, toNumber(global.innerHeight, doc?.clientHeight || 0))
    };
  };
  const normalizedRect = (element) => {
    const rect = element?.getBoundingClientRect?.();
    if (!rect) return { left:0, top:0, right:0, bottom:0, width:0, height:0, x:0, y:0 };
    const left = toNumber(rect.left ?? rect.x, 0);
    const top = toNumber(rect.top ?? rect.y, 0);
    const width = Math.max(0, toNumber(rect.width, toNumber(rect.right, left) - left));
    const height = Math.max(0, toNumber(rect.height, toNumber(rect.bottom, top) - top));
    return {
      left,
      top,
      right: toNumber(rect.right, left + width),
      bottom: toNumber(rect.bottom, top + height),
      width,
      height,
      x:left,
      y:top
    };
  };
  const splitPlacement = (placement) => {
    const raw = String(placement || 'bottom').toLowerCase();
    const [side, align] = raw.split('-');
    return {
      side: ['top','right','bottom','left'].includes(side) ? side : 'bottom',
      align: ['start','end'].includes(align) ? align : 'center'
    };
  };
  const oppositeSide = (side) => ({ top:'bottom', bottom:'top', left:'right', right:'left' }[side] || 'bottom');
  const buildPlacement = (side, align) => align && align !== 'center' ? `${side}-${align}` : side;
  const baseCoords = (reference, floating, side, align, gap) => {
    let x = reference.left + (reference.width - floating.width) / 2;
    let y = reference.top + (reference.height - floating.height) / 2;
    if (side === 'top') y = reference.top - floating.height - gap;
    else if (side === 'bottom') y = reference.bottom + gap;
    else if (side === 'left') x = reference.left - floating.width - gap;
    else if (side === 'right') x = reference.right + gap;

    if (side === 'top' || side === 'bottom') {
      if (align === 'start') x = reference.left;
      else if (align === 'end') x = reference.right - floating.width;
    } else {
      if (align === 'start') y = reference.top;
      else if (align === 'end') y = reference.bottom - floating.height;
    }
    return { x, y };
  };
  const overflowScore = (coords, floating, padding) => {
    const vp = viewport();
    return Math.max(0, padding.left - coords.x)
      + Math.max(0, padding.top - coords.y)
      + Math.max(0, coords.x + floating.width + padding.right - vp.width)
      + Math.max(0, coords.y + floating.height + padding.bottom - vp.height);
  };

  function offset(value = 0) {
    return { name:'offset', options:value };
  }
  function flip(options = {}) {
    return { name:'flip', options:options || {} };
  }
  function shift(options = {}) {
    return { name:'shift', options:options || {} };
  }
  function size(options = {}) {
    return { name:'size', options:options || {} };
  }

  async function computePosition(referenceElement, floatingElement, options = {}) {
    if (!referenceElement?.getBoundingClientRect || !floatingElement?.getBoundingClientRect) {
      throw new TypeError('computePosition requires reference and floating elements.');
    }
    const middleware = Array.isArray(options.middleware) ? options.middleware.filter(Boolean) : [];
    const preferred = splitPlacement(options.placement || 'bottom');
    const offsetMiddleware = middleware.find((entry) => entry?.name === 'offset');
    let gap = 0;
    if (offsetMiddleware) {
      const raw = typeof offsetMiddleware.options === 'function'
        ? offsetMiddleware.options({ placement:buildPlacement(preferred.side, preferred.align) })
        : offsetMiddleware.options;
      gap = typeof raw === 'number' ? toNumber(raw, 0) : toNumber(raw?.mainAxis, 0);
    }

    const reference = normalizedRect(referenceElement);
    const floating = normalizedRect(floatingElement);
    let side = preferred.side;
    const align = preferred.align;
    let coords = baseCoords(reference, floating, side, align, gap);

    const flipMiddleware = middleware.find((entry) => entry?.name === 'flip');
    if (flipMiddleware) {
      const padding = paddingValue(flipMiddleware.options?.padding || 0);
      const candidateSide = oppositeSide(side);
      const candidateCoords = baseCoords(reference, floating, candidateSide, align, gap);
      if (overflowScore(candidateCoords, floating, padding) < overflowScore(coords, floating, padding)) {
        side = candidateSide;
        coords = candidateCoords;
      }
    }

    const shiftMiddleware = middleware.find((entry) => entry?.name === 'shift');
    if (shiftMiddleware) {
      const padding = paddingValue(shiftMiddleware.options?.padding || 0);
      const vp = viewport();
      const minX = padding.left;
      const minY = padding.top;
      const maxX = Math.max(minX, vp.width - floating.width - padding.right);
      const maxY = Math.max(minY, vp.height - floating.height - padding.bottom);
      coords.x = Math.min(Math.max(coords.x, minX), maxX);
      coords.y = Math.min(Math.max(coords.y, minY), maxY);
    }

    const sizeMiddleware = middleware.find((entry) => entry?.name === 'size');
    if (sizeMiddleware && typeof sizeMiddleware.options?.apply === 'function') {
      const padding = paddingValue(sizeMiddleware.options?.padding || 0);
      const vp = viewport();
      const availableWidth = Math.max(0, vp.width - padding.left - padding.right);
      const availableHeight = Math.max(0, vp.height - padding.top - padding.bottom);
      await sizeMiddleware.options.apply({
        availableWidth,
        availableHeight,
        rects:{ reference, floating },
        elements:{ reference:referenceElement, floating:floatingElement },
        placement:buildPlacement(side, align)
      });
    }

    return {
      x:coords.x,
      y:coords.y,
      placement:buildPlacement(side, align),
      strategy:String(options.strategy || 'absolute'),
      middlewareData:{}
    };
  }

  function autoUpdate(referenceElement, floatingElement, update, options = {}) {
    if (typeof update !== 'function') return () => {};
    let frame = 0;
    let stopped = false;
    const schedule = () => {
      if (stopped || frame) return;
      const raf = global.requestAnimationFrame || ((fn) => global.setTimeout(fn, 16));
      frame = raf(() => {
        frame = 0;
        if (!stopped) update();
      });
    };
    const onChange = () => schedule();
    global.addEventListener?.('resize', onChange, { passive:true });
    global.addEventListener?.('scroll', onChange, { passive:true, capture:true });

    let resizeObserver = null;
    if (typeof global.ResizeObserver === 'function') {
      resizeObserver = new global.ResizeObserver(onChange);
      try { resizeObserver.observe(referenceElement); } catch (_) {}
      try { resizeObserver.observe(floatingElement); } catch (_) {}
    }

    let animationFrame = 0;
    if (options.animationFrame) {
      let lastRef = normalizedRect(referenceElement);
      const loop = () => {
        if (stopped) return;
        const next = normalizedRect(referenceElement);
        if (next.left !== lastRef.left || next.top !== lastRef.top || next.width !== lastRef.width || next.height !== lastRef.height) {
          lastRef = next;
          schedule();
        }
        animationFrame = global.requestAnimationFrame?.(loop) || 0;
      };
      animationFrame = global.requestAnimationFrame?.(loop) || 0;
    }

    update();
    return () => {
      stopped = true;
      global.removeEventListener?.('resize', onChange);
      global.removeEventListener?.('scroll', onChange, true);
      resizeObserver?.disconnect?.();
      if (frame) {
        if (global.cancelAnimationFrame) global.cancelAnimationFrame(frame);
        else global.clearTimeout?.(frame);
      }
      if (animationFrame && global.cancelAnimationFrame) global.cancelAnimationFrame(animationFrame);
      frame = 0;
      animationFrame = 0;
    };
  }

  global.FloatingUIDOM = Object.assign({}, global.FloatingUIDOM || {}, {
    autoUpdate,
    computePosition,
    flip,
    offset,
    shift,
    size,
    __zefirokLocal:true
  });
})(typeof globalThis !== 'undefined' ? globalThis : (typeof window !== 'undefined' ? window : this));
